# construct semantic object cells from the original input grid g (still original? REPL g was modified earlier; use s reparse)
orig=[list(map(int,r.split())) for r in s.splitlines()]
objs={c:{(r,x) for r,row in enumerate(orig) for x,v in enumerate(row) if v==c} for c in (1,4,5,6,8,9)}
marks={5:{(2,15),(4,15),(5,10),(5,13)},8:{(1,19),(1,23),(5,23),(6,21)},9:{(10,3),(10,7)},4:{(13,12),(15,16),(16,13)},6:{(22,3),(22,7)},1:{(19,22),(22,18),(24,18),(25,22)}}
shift={6:(-19,0),9:(-7,0),4:(0,0),5:(11,-3),8:(6,-11),1:(-7,-2)}
out=[[0]*26 for _ in range(26)]; conflicts=[]
for col in objs:
 dy,dx=shift[col]
 for r,c in objs[col]:
  p=(r+dy,c+dx)
  if not(0<=p[0]<26 and 0<=p[1]<26): print('bounds',col,p);continue
  if out[p[0]][p[1]]: conflicts.append((col,p,out[p[0]][p[1]]))
  out[p[0]][p[1]]=col
for col,ps in marks.items():
 dy,dx=shift[col]
 for r,c in ps:
  p=(r+dy,c+dx)
  if out[p[0]][p[1]] and out[p[0]][p[1]]!=2: conflicts.append(('marker conflict',col,p,out[p[0]][p[1]]))
  out[p[0]][p[1]]=2
print('conflicts',conflicts)
print('\n'.join(' '.join(map(str,row)) for row in out))
